  admin=browser.new_page(viewport={'width':1440,'height':1000});admin.on('pageerror',lambda e:errors.append(str(e)+' '+e.stack));login(admin,'vpm_local_admin',(ROOT/'.runtime/admin-password').read_text().strip());admin.goto(BASE+'/wp-admin/tools.php?page=vpm-booking-operations',wait_until='networkidle');review=admin.locator('form:has(input[name="vpm_operation"][value="message_review"])');check(review.count()==1,'Platform has separate pending-message review queue');directory=ROOT/'zwischenstand/buchungskern';review.screenshot(path=str(directory/'plattform-nachrichtenfreigabe-test.png'));review.get_by_role('button',name='Freigeben',exact=True).click();admin.wait_for_load_state('networkidle');check(php('global $wpdb;echo $wpdb->get_var("SELECT COUNT(*) FROM ".VPM\\Booking\\DB::table("outbox")." WHERE topic=\'booking.partner_message_approved\'");')=='1','Platform approval queues exactly one customer message');profile=admin.locator('form:has(input[name="vpm_operation"][value="profile_review"])');profile.get_by_role('button',name='Geprüfte Angaben freigeben').click();admin.wait_for_load_state('networkidle');check(php('echo VPM\\Booking\\Logistics::get('+str(data['partner'])+')["points"]["handover"]["instructions_de"];')=='Neue Anfahrtshinweise zur Prüfung.','Reviewed profile becomes active only after platform approval')
  owner.goto(portal+'#bookings',wait_until='networkidle');owner.locator('#bookings').screenshot(path=str(directory/'partnerkontakt-ohne-kundenmail-test.png'));check('hidden-browser-customer@example.invalid'not in owner.content(),'Customer address remains absent after review workflow');check(not errors,'No browser errors in separate owner and admin sessions: '+repr(errors));browser.close()
